/**
 * Check if element has overflown by its children
 * @param {HTMLElement} element target element to check
 * @return {boolean} returns true if the children is overflow by its parent
 */
export function isOverflown(element: HTMLElement): boolean {
  return element.scrollHeight > element.clientHeight || element.scrollWidth > element.clientWidth || element.offsetWidth < element.scrollWidth;
}
